package gui

import (
	"encoding/json"
	"fmt"
	"sync"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/container"
	"fyne.io/fyne/v2/driver/desktop"
	"fyne.io/fyne/v2/layout"
	"fyne.io/fyne/v2/theme"
	"fyne.io/fyne/v2/widget"
	fyneX "fyne.io/x/fyne/widget"
	"github.com/0xAX/notificator"
	pluggable "github.com/mudler/go-pluggable"
	"go.deanishe.net/fuzzy"
)

type Launcher struct {
	sync.Mutex
	pluginDir   string
	window      fyne.Window
	manager     *pluggable.Manager
	notifier    *notificator.Notificator
	defaultSize fyne.Size
	responses   map[pluggable.EventType]map[*pluggable.Plugin]*pluggable.EventResponse
}

const (
	searchEvent pluggable.EventType = "search"
	submitEvent pluggable.EventType = "submit"
	appName     string              = "golauncher"
)

func listSize(n int) float32 {
	l := widget.NewList(func() int { return 1 }, func() fyne.CanvasObject { return widget.NewEntry() }, func(lii widget.ListItemID, f fyne.CanvasObject) {})
	ss := l.MinSize()
	return float32(n)*(ss.Height+2*theme.Padding()+theme.SeparatorThicknessSize()) + theme.Padding()
}

func (c *Launcher) Reload(app fyne.App) {

	entry := fyneX.NewCompletionEntry([]string{})
	entry.Wrapping = fyne.TextWrapBreak

	var selection interface{}

	entry.OnMenuNavigation = func(w widget.ListItemID) {
		selection = true
	}

	entry.OnTypeEvent = func(event *fyne.KeyEvent) {
		switch event.Name {
		case fyne.KeyEscape:
			// Quit the app if the user press esc
			app.Quit()
		}
	}

	entry.OnSubmitted = func(s string) {
		if len(s) == 0 {
			// Quit the app if the user submit no results
			app.Quit()
		}

		if len(s) < 3 {
			return
		}

		if selection == nil {
			// Nothing was selected and user hit enter
			// act as user selected the first item
			if len(entry.Options) > 0 {
				s = entry.Options[0]
			}
		}

		res := c.pluginSubmit(submitEvent, s)
		for _, r := range res {
			r.notify(c.notifier)
		}

		app.Quit()
	}

	noResults := func() {
		c.window.Resize(c.defaultSize)
		entry.HideCompletion()
	}

	// When the use typed text, complete the list.
	entry.OnChanged = func(s string) {
		// completion start for text length >= 3
		if len(s) < 3 {
			noResults()
			return
		}

		var results []string
		res := c.pluginSubmit(searchEvent, s)
		for _, r := range res {
			for _, r := range r.Responses() {
				if r != "" {
					results = append(results, r)
				}
			}
		}

		// no results
		if len(results) == 0 {
			noResults()
			return
		}

		fuzzy.SortStrings(results, s)

		// then show them
		entry.SetOptions(results)

		// resize the window based on the option results
		ls := listSize(len(results))
		if ls > 480/2 {
			ls = 480 / 2
		}

		c.window.Resize(c.defaultSize.Add(fyne.NewSize(0, ls)))

		entry.ShowCompletion()
	}

	s := container.NewBorder(entry, nil, nil, nil, layout.NewSpacer())
	c.window.SetContent(
		container.NewAdaptiveGrid(1, s),
	)
	c.window.Canvas().Focus(entry)

}

func (c *Launcher) responseHandler(ev pluggable.EventType) func(p *pluggable.Plugin, r *pluggable.EventResponse) {
	return func(p *pluggable.Plugin, r *pluggable.EventResponse) {
		c.Lock()
		if _, exists := c.responses[ev]; !exists {
			c.responses[ev] = make(map[*pluggable.Plugin]*pluggable.EventResponse)
		}
		c.responses[ev][p] = r
		c.Unlock()
	}
}

type pluginResult struct {
	plugin   *pluggable.Plugin
	response *pluggable.EventResponse
}

func (p pluginResult) Responses() []string {
	pr := &struct {
		Response []string
	}{}
	json.Unmarshal([]byte(p.response.Data), pr)
	return pr.Response
}

func (p pluginResult) notify(n *notificator.Notificator) {
	title := fmt.Sprintf("%s %s", appName, p.plugin.Name)
	if p.response.Errored() {
		n.Push(title, p.response.Error, "", notificator.UR_CRITICAL)
	}
	if p.response.State != "" {
		n.Push(title, p.response.State, "", notificator.UR_NORMAL)
	}
}

func (c *Launcher) pluginSubmit(ev pluggable.EventType, input string) (res []*pluginResult) {
	c.manager.Publish(ev, struct{ Term string }{Term: input})
	for p, r := range c.responses[ev] {
		res = append(res, &pluginResult{plugin: p, response: r})
	}
	return
}

func (c *Launcher) loadUI(app fyne.App) {
	pluginsDir := c.pluginDir
	if pluginsDir == "" {
		pluginsDir = "plugins"
	}

	c.manager.Autoload(appName, pluginsDir)
	c.manager.Register()
	c.manager.Response(submitEvent, c.responseHandler(submitEvent))
	c.manager.Response(searchEvent, c.responseHandler(searchEvent))

	drv := fyne.CurrentApp().Driver()
	if drv, ok := drv.(desktop.Driver); ok {
		c.window = drv.CreateSplashWindow()
	} else {
		c.window = app.NewWindow(appName)
	}

	c.Reload(app)

	c.window.SetFixedSize(true)

	c.window.Resize(c.defaultSize)
	c.window.SetPadded(true)
	c.window.CenterOnScreen()

	c.window.Show()
}

func newLauncher(pluginDir string) *Launcher {
	return &Launcher{
		pluginDir:   pluginDir,
		defaultSize: fyne.NewSize(640, listSize(1)),
		notifier: notificator.New(notificator.Options{
			AppName: appName,
		}),
		manager: pluggable.NewManager(
			[]pluggable.EventType{
				submitEvent,
				searchEvent,
			},
		),
		responses: make(map[pluggable.EventType]map[*pluggable.Plugin]*pluggable.EventResponse),
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"net/url"

	"github.com/mudler/go-pluggable"
	"mvdan.cc/xurls/v2"
)

func mapS(s []string, m string) (res []string) {
	for _, r := range s {

		URL, _ := url.Parse(r)

		if URL.Scheme == "" {
			URL.Scheme = "https"
		}
		res = append(res, m+URL.String())
	}
	return res
}

func main() {
	xurlsRelaxed := xurls.Relaxed()
	var (
		submit pluggable.EventType = "submit"
		search pluggable.EventType = "search"
	)

	factory := pluggable.NewPluginFactory()

	factory.Add(submit, func(e *pluggable.Event) pluggable.EventResponse {
		d := &struct{ Term string }{}
		json.Unmarshal([]byte(e.Data), d)
		s := ""
		if strings.Contains(d.Term, "Open url: ") {
			u := strings.ReplaceAll(d.Term, "Open url: ", "")
			cmd := exec.Command("xdg-open", u)
			s = fmt.Sprintf("opening %s", u)
			cmd.Start()
			go func() {
				cmd.Wait()
			}()
		}
		return pluggable.EventResponse{State: s}
	})

	factory.Add(search, func(e *pluggable.Event) pluggable.EventResponse {
		d := &struct{ Term string }{}
		json.Unmarshal([]byte(e.Data), d)
		res := mapS(xurlsRelaxed.FindAllString(d.Term, -1), "Open url: ")

		b, _ := json.Marshal(struct{ Response []string }{Response: res})
		return pluggable.EventResponse{Data: string(b)}
	})

	factory.Run(pluggable.EventType(os.Args[1]), os.Args[2], os.Stdout)
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/mudler/go-pluggable"
	"github.com/sahilm/fuzzy"
)

func listDir(dir string) []string {
	content := []string{}

	filepath.Walk(dir,
		func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if !info.IsDir() {
				content = append(content, path)
			}

			return nil
		})

	return content
}

func ff(f string) (res []string) {
	paths := strings.Split(os.Getenv("PATH"), ":")
	bins := []string{}
	for _, p := range paths {
		bins = append(bins, listDir(p)...)
	}

	m := fuzzy.Find(f, bins)
	for _, match := range m {
		res = append(res, match.Str)
	}

	// Cut results to first ten
	if len(res) > 10 {
		res = res[0:10]
	}

	return
}

type res struct {
	Term string
}

func mapS(s []string, m string) (res []string) {
	for _, r := range s {
		res = append(res, m+r)
	}
	return res
}

func main() {

	var (
		submit pluggable.EventType = "submit"
		search pluggable.EventType = "search"
	)

	factory := pluggable.NewPluginFactory()

	factory.Add(submit, func(e *pluggable.Event) pluggable.EventResponse {
		d := &res{}
		json.Unmarshal([]byte(e.Data), d)
		s := ""
		if strings.Contains(d.Term, "Execute: ") {
			proc := strings.ReplaceAll(d.Term, "Execute: ", "")
			cmd := exec.Command(proc)
			s = fmt.Sprintf("opening %s", proc)
			cmd.Start()
			go func() {
				cmd.Wait()
			}()
		}
		return pluggable.EventResponse{State: s}
	})

	factory.Add(search, func(e *pluggable.Event) pluggable.EventResponse {
		d := &res{}
		json.Unmarshal([]byte(e.Data), d)
		res := mapS(ff(d.Term), "Execute: ")
		b, _ := json.Marshal(struct{ Response []string }{Response: res})
		return pluggable.EventResponse{Data: string(b)}
	})

	factory.Run(pluggable.EventType(os.Args[1]), os.Args[2], os.Stdout)
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"

	"image/png"

	"github.com/kbinani/screenshot"
	"github.com/mudler/go-pluggable"
)

func fork() {
	exec.Command("/proc/self/exe",
		"_screenshot",
	).Start()
}

func takeScreenshot() {
	time.Sleep(1 * time.Second)
	n := screenshot.NumActiveDisplays()
	for i := 0; i < n; i++ {
		bounds := screenshot.GetDisplayBounds(i)

		img, err := screenshot.CaptureRect(bounds)
		if err != nil {
			panic(err)
		}
		os.MkdirAll("/tmp/screenshots", os.ModePerm)
		fileName := fmt.Sprintf("/tmp/screenshots/%d_%dx%d.png", i, bounds.Dx(), bounds.Dy())
		file, _ := os.Create(fileName)
		defer file.Close()
		png.Encode(file, img)
	}
	// Open screenshot folder
	exec.Command("xdg-open", "/tmp/screenshots").Run()
}

func main() {
	var (
		submit pluggable.EventType = "submit"
		search pluggable.EventType = "search"
	)

	if os.Args[1] == "_screenshot" {
		takeScreenshot()
	}

	factory := pluggable.NewPluginFactory()

	factory.Add(submit, func(e *pluggable.Event) pluggable.EventResponse {
		d := &struct {
			Term string
		}{}
		json.Unmarshal([]byte(e.Data), d)

		s := ""

		if strings.Contains(d.Term, "Take screenshot") {
			s = "Taking screenshots in /tmp/screenshots"
			fork()
		}
		return pluggable.EventResponse{State: s}
	})

	factory.Add(search, func(e *pluggable.Event) pluggable.EventResponse {
		d := &struct {
			Term string
		}{}
		json.Unmarshal([]byte(e.Data), d)
		if strings.Contains(strings.ToLower(d.Term), "screen") || strings.Contains(strings.ToLower(d.Term), "take") {
			b, _ := json.Marshal(struct{ Response []string }{Response: []string{"Take screenshot"}})
			return pluggable.EventResponse{Data: string(b)}
		}
		return pluggable.EventResponse{}
	})

	factory.Run(pluggable.EventType(os.Args[1]), os.Args[2], os.Stdout)
}

